package in.aicon.pocket;
import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class LedgerSyncStoreTest {
 SQLiteDatabase db;LedgerSyncStore store;String subject="345678901234567890123";
 @Before public void setup()throws Exception{Context c=RuntimeEnvironment.getApplication();String name=AccountScope.databaseFor(subject);c.deleteDatabase(name);db=c.openOrCreateDatabase(name,0,null);store=new LedgerSyncStore(db,subject);}
 @After public void close(){db.close();}
 JSONObject loan(String id)throws Exception{return LedgerWire.transaction(id,"lent",50000,"2026-11-11","Cash","","Debt","","Sample","");}
 void put(String table,JSONObject json)throws Exception{ContentValues v=new ContentValues();Iterator<String> keys=json.keys();while(keys.hasNext()){String k=keys.next();if(k.equals("type"))continue;Object o=json.get(k);if(o instanceof Number)v.put(k,((Number)o).longValue());else v.put(k,o.toString());}db.insertOrThrow(table,null,v);}
 long count(String table){try(Cursor c=db.rawQuery("SELECT count(*) FROM "+table,null)){c.moveToFirst();return c.getLong(0);}}
 void capture()throws Exception{db.beginTransaction();try{store.captureLocalEdits();db.setTransactionSuccessful();}finally{db.endTransaction();}}
 @Test public void transactionsBudgetsGoalsCaptureAndReloadAtomically()throws Exception{
  String id=UUID.randomUUID().toString(),goal=UUID.randomUUID().toString(),budget=UUID.randomUUID().toString();put("tx",loan(id));put("budgets",LedgerWire.budget(budget,"Food",30000));put("goals",LedgerWire.goal(goal,"Laptop",500000,10000));capture();assertEquals(7,store.snapshot().records.size());assertEquals(7,store.pending().size());
  Map<String,SyncModel.Record> remote=new TreeMap<>(store.snapshot().records);JSONObject changed=loan(id).put("note","Edited on another device");remote.put(id,remote.get(id).edit("other",changed.toString(),false));long oldId;try(Cursor c=db.rawQuery("SELECT id FROM tx",null)){c.moveToFirst();oldId=c.getLong(0);}assertTrue(store.commitMerge(store.snapshot().revision,remote));try(Cursor c=db.rawQuery("SELECT id,note FROM tx",null)){c.moveToFirst();assertEquals(oldId,c.getLong(0));assertEquals("Edited on another device",c.getString(1));}assertEquals(1,count("budgets"));assertEquals(1,count("goals"));
 }
 @Test public void invalidCombinedRepaymentsKeepAllTablesAndOutbox()throws Exception{
  String id=UUID.randomUUID().toString();put("tx",loan(id));capture();Map<String,SyncModel.Record> merged=new TreeMap<>(store.snapshot().records);
  for(int i=0;i<2;i++){String payment=UUID.randomUUID().toString();JSONObject j=LedgerWire.transaction(payment,"repay_in",30000,"2026-11-11","Cash","","Debt","","Sample",id);merged.put(payment,new SyncModel.Record(payment,j.toString(),false,Collections.singletonMap("other",1L)));}
  long revision=store.snapshot().revision;int pending=store.pending().size();try{store.commitMerge(revision,merged);fail();}catch(IllegalArgumentException expected){}assertEquals(revision,store.snapshot().revision);assertEquals(1,count("tx"));assertEquals(pending,store.pending().size());
 }
 @Test public void deleteGoalAndRecreateGetsNewIdentity()throws Exception{
  String id=UUID.randomUUID().toString();put("goals",LedgerWire.goal(id,"Laptop",500000,0));capture();db.delete("goals",null,null);capture();assertTrue(store.snapshot().records.get(id).deleted);String replacement=UUID.randomUUID().toString();put("goals",LedgerWire.goal(replacement,"Laptop",500000,0));capture();assertTrue(store.snapshot().records.get(id).deleted);assertFalse(store.snapshot().records.get(replacement).deleted);
 }
 @Test public void captureRollbackRestoresOriginalLedger()throws Exception{
  String id=UUID.randomUUID().toString();db.beginTransaction();try{put("tx",loan(id));store.captureLocalEdits();}finally{db.endTransaction();}assertEquals(0,count("tx"));assertTrue(store.snapshot().records.isEmpty());assertTrue(store.pending().isEmpty());
 }
 @Test public void catalogRenameResolvesExistingReferenceAndPreferenceRoundTrips()throws Exception{
  String id=UUID.randomUUID().toString(),budget=UUID.randomUUID().toString();put("tx",loan(id));put("budgets",LedgerWire.budget(budget,"Food",30000));capture();Map<String,SyncModel.Record> merged=new TreeMap<>(store.snapshot().records);String cashId=null,personId=null;for(SyncModel.Record r:merged.values()){JSONObject j=new JSONObject(r.payload);if(j.optString("type").equals("catalog")){if(j.getString("name").equals("Cash"))cashId=r.id;if(j.getString("name").equals("Sample"))personId=r.id;}}
  assertNotNull(cashId);assertNotNull(personId);JSONObject cash=new JSONObject(merged.get(cashId).payload).put("name","Daily funds");merged.put(cashId,merged.get(cashId).edit("other",cash.toString(),false));JSONObject person=new JSONObject(merged.get(personId).payload).put("name","Renamed sample");merged.put(personId,merged.get(personId).edit("other",person.toString(),false));JSONObject pref=new JSONObject(merged.get(LedgerWire.PREFERENCES_ID).payload);pref.getJSONObject("values").put("palette","Violet").put("dateFormat","dd/MM/yyyy");merged.put(LedgerWire.PREFERENCES_ID,merged.get(LedgerWire.PREFERENCES_ID).edit("other",pref.toString(),false));assertTrue(store.commitMerge(store.snapshot().revision,merged));try(Cursor c=db.rawQuery("SELECT account,person FROM tx WHERE uuid=?",new String[]{id})){assertTrue(c.moveToFirst());assertEquals("Daily funds",c.getString(0));assertEquals("Renamed sample",c.getString(1));}assertEquals("Violet",new SettingsStore(db).get("palette"));assertEquals(cashId,new CatalogStore(db).find("account","Daily funds").id);capture();JSONObject payload=new JSONObject(store.snapshot().records.get(id).payload);assertEquals(cashId,payload.getString("accountId"));assertFalse(payload.has("account"));assertEquals("INR",payload.getString("currency"));
 }
 @Test public void wrongEntityReferenceAndMixedCurrencyRejectAtomically()throws Exception{String id=UUID.randomUUID().toString();put("tx",loan(id));capture();long revision=store.snapshot().revision;Map<String,SyncModel.Record> merged=new TreeMap<>(store.snapshot().records);JSONObject bad=new JSONObject(merged.get(id).payload);bad.put("accountId",bad.getString("personId"));merged.put(id,merged.get(id).edit("other",bad.toString(),false));try{store.commitMerge(revision,merged);fail();}catch(IllegalArgumentException expected){}assertEquals(revision,store.snapshot().revision);merged=new TreeMap<>(store.snapshot().records);JSONObject pref=new JSONObject(merged.get(LedgerWire.PREFERENCES_ID).payload);pref.getJSONObject("values").put("currency","USD");merged.put(LedgerWire.PREFERENCES_ID,merged.get(LedgerWire.PREFERENCES_ID).edit("other",pref.toString(),false));try{store.commitMerge(revision,merged);fail();}catch(IllegalArgumentException expected){}assertEquals("INR",new SettingsStore(db).get("currency"));assertEquals(revision,store.snapshot().revision);}
 @Test public void sameSeedLabelsHaveSameIdsAcrossFreshDevices()throws Exception{CatalogStore first=new CatalogStore(db);first.seed(new String[]{"Food"},new String[]{"Cash"});String id=first.find("account","Cash").id;SQLiteDatabase other=SQLiteDatabase.create(null);try{LedgerSyncStore.schema(other);CatalogStore second=new CatalogStore(other);second.seed(new String[]{"Food"},new String[]{"Cash"});assertEquals(id,second.find("account","Cash").id);CatalogStore.Item cash=second.find("account","Cash");second.put(cash.id,"account","Purse",22,"Teal");ContentValues row=new ContentValues();row.put("uuid",UUID.randomUUID().toString());row.put("kind","income");row.put("amount",100);row.put("day","2026-11-11");row.put("account","Cash");row.put("dest","");row.put("category","Food");row.put("note","");other.insertOrThrow("tx",null,row);second.seed(new String[]{"Food"},new String[]{"Cash"});assertNotNull(second.find("account","Cash"));assertFalse(cash.id.equals(second.find("account","Cash").id));}finally{other.close();}}

 @Test public void threeWayConflictRetainsEveryChoiceAndResolutionDominatesAll()throws Exception{String id=UUID.randomUUID().toString();put("tx",loan(id));capture();SyncEngine.Snapshot before=store.snapshot();SyncModel.Record base=before.records.get(id);List<SyncModel.Record> alternatives=new ArrayList<>();for(String device:new String[]{"device_a","device_b","device_c"})alternatives.add(base.edit(device,new JSONObject(base.payload).put("note",device).toString(),false));SyncModel.Conflict conflict=null;try{SyncModel.mergeRecords(alternatives);fail();}catch(SyncModel.Conflict e){conflict=e;}assertEquals(3,conflict.versions.size());store.retainConflict(before.revision,conflict);assertEquals(3,store.conflict().conflict.versions.size());store.resolveConflict(store.conflict().key,before.revision,2,false);assertNull(store.conflict());assertEquals("device_c",new JSONObject(store.snapshot().records.get(id).payload).getString("note"));alternatives.add(store.snapshot().records.get(id));assertEquals(store.snapshot().records.get(id).payload,SyncModel.mergeRecords(alternatives).payload);}
 @Test public void staleReviewDoesNotOverwriteNewLocalEdit()throws Exception{String id=UUID.randomUUID().toString();put("tx",loan(id));capture();SyncEngine.Snapshot before=store.snapshot();SyncModel.Record base=before.records.get(id);SyncModel.Conflict conflict=new SyncModel.Conflict(base.edit("device_a",new JSONObject(base.payload).put("note","A").toString(),false),base.edit("device_b",new JSONObject(base.payload).put("note","B").toString(),false));store.retainConflict(before.revision,conflict);ContentValues v=new ContentValues();v.put("note","New local edit");db.update("tx",v,"uuid=?",new String[]{id});capture();try{store.resolveConflict(store.conflict().key,before.revision,0,false);fail();}catch(IllegalStateException expected){}assertEquals("New local edit",new JSONObject(store.snapshot().records.get(id).payload).getString("note"));assertNotNull(store.conflict());}

 @Test public void multipleConflictChoicesApplyWholeCandidateLedgerOnlyAfterFinalReview()throws Exception{String first=UUID.randomUUID().toString(),second=UUID.randomUUID().toString(),newGoal=UUID.randomUUID().toString();put("tx",loan(first));put("goals",LedgerWire.goal(second,"Trip",100000,0));capture();SyncEngine.Snapshot before=store.snapshot();Map<String,List<SyncModel.Record>> candidates=new TreeMap<>();for(SyncModel.Record r:before.records.values())candidates.put(r.id,Collections.singletonList(r));for(String id:new String[]{first,second}){SyncModel.Record base=before.records.get(id);JSONObject left=new JSONObject(base.payload),right=new JSONObject(base.payload);String key=id.equals(first)?"note":"name";left.put(key,"Version A");right.put(key,"Version B");candidates.put(id,Arrays.asList(base.edit("device_a",left.toString(),false),base.edit("device_b",right.toString(),false)));}candidates.put(newGoal,Collections.singletonList(new SyncModel.Record(newGoal,LedgerWire.goal(newGoal,"New remote plan",40000,0).toString(),false,Collections.singletonMap("device_c",1L))));SyncModel.Conflict conflict=new SyncModel.Conflict(candidates.get(first));store.retainConflict(before.revision,conflict,candidates);assertFalse(store.resolveConflict(store.conflict().key,before.revision,0,false));assertEquals(before.revision,store.snapshot().revision);assertEquals(1,count("goals"));assertEquals(second,store.conflict().id);assertTrue(store.resolveConflict(store.conflict().key,before.revision,1,false));assertNull(store.conflict());assertEquals(2,count("goals"));assertEquals("Version A",new JSONObject(store.snapshot().records.get(first).payload).getString("note"));assertEquals("Version B",new JSONObject(store.snapshot().records.get(second).payload).getString("name"));}

 @Test public void firstEmptyCloudSyncKeepsUncommittedStarterCatalogAndEmptyHistory()throws Exception{CatalogStore catalog=new CatalogStore(db);catalog.seed(new String[]{"Food","Other"},new String[]{"Cash"});assertTrue(store.snapshot().records.isEmpty());assertTrue(store.commitMerge(store.snapshot().revision,Collections.emptyMap()));assertEquals(2,catalog.list("category").size());assertEquals(1,catalog.list("account").size());assertTrue(store.snapshot().records.isEmpty());assertTrue(store.pending().isEmpty());}
 @Test public void emptyCatalogPlaceholdersNeverReuseDeletedCloudIdentities()throws Exception{CatalogStore catalog=new CatalogStore(db);catalog.seed(new String[]{"Other"},new String[]{"Cash"});String oldCash=catalog.find("account","Cash").id;capture();Map<String,SyncModel.Record> removed=new TreeMap<>();for(SyncModel.Record record:store.snapshot().records.values())removed.put(record.id,record.id.equals(LedgerWire.PREFERENCES_ID)?record:record.edit("other",null,true));assertTrue(store.commitMerge(store.snapshot().revision,removed));assertTrue(catalog.list("account").isEmpty());catalog.ensureUsable();assertNotEquals(oldCash,catalog.find("account","Cash").id);capture();assertTrue(store.snapshot().records.get(oldCash).deleted);assertFalse(store.snapshot().records.get(catalog.find("account","Cash").id).deleted);}

 @Test public void mergedQuickDefaultCannotSilentlySelectMissingOrWrongAccount()throws Exception{CatalogStore catalog=new CatalogStore(db);catalog.seed(new String[]{"Food"},new String[]{"Cash"});capture();SyncEngine.Snapshot before=store.snapshot();Map<String,SyncModel.Record> merged=new TreeMap<>(before.records);SyncModel.Record pref=merged.get(LedgerWire.PREFERENCES_ID);JSONObject payload=new JSONObject(pref.payload);payload.getJSONObject("values").put("defaultAccount",catalog.find("category","Food").id);merged.put(pref.id,pref.edit("other",payload.toString(),false));try{store.commitMerge(before.revision,merged);fail();}catch(IllegalArgumentException expected){}assertEquals(before.revision,store.snapshot().revision);assertEquals("",new SettingsStore(db).get("defaultAccount"));}

}
